(()=>{'use strict';const C=ArcadeCore;const list=document.getElementById('game-list');if(!list)return;
const rules={brick:'패들로 공을 튕겨 3단계를 완성합니다. 목숨 3개, 벽돌당 10점·단계당 50점. ←/→·마우스·터치로 이동하며 Space 또는 발사 버튼으로 시작합니다.',shisen:'같은 문양 두 개를 최대 두 번 꺾어 연결합니다. 바깥 한 칸을 돌아갈 수 있습니다. 짝당 100점·힌트 −20점, 막히면 남은 문양 자동 재배치.',pop:'같은 색이 상하좌우로 2개 이상 이어진 그룹을 골라 제거합니다. 아래로 낙하하고 빈 열은 왼쪽으로 모입니다. n×(n−1)×5점, 전부 제거 +500점.',bubble:'조준 후 발사해 같은 색 3개 이상을 연결합니다. 벽 반사 가능. 연결 제거 개당10점·천장과 분리된 버블20점. 40발 안에 전부 제거하면 성공합니다.'};
list.insertAdjacentHTML('beforeend',Object.entries(C.GAMES).map(([id,g])=>`<article class="game-card arcade-card ${id}"><a class="game-launch" href="${g.route}" aria-label="${g.name} 바로 플레이"><span class="card-cover"><img src="assets/arcade-${id}.svg" width="326" height="140" alt="" loading="lazy"></span><span class="card-body"><strong class="game-name">${g.name}</strong><span class="game-intro">${g.tag}</span><span class="tags"><span>오락실</span></span><span class="card-play">바로 플레이 →</span></span></a><button class="card-rules" data-arcade-rules="${id}" aria-label="${g.name} 방법 보기">방법 보기</button></article>`).join(''));
function badge(){try{const store=ArcadeStore.create(localStorage);for(const id of Object.keys(C.GAMES)){const s=store.load(id).state,el=document.querySelector(`.arcade-card.${id} .card-play`);if(el)el.textContent=s?.status==='playing'&&s.revision>0?'이어서 플레이 →':'바로 플레이 →';}}catch{}}
list.addEventListener('click',e=>{const b=e.target.closest('[data-arcade-rules]');if(!b)return;const id=b.dataset.arcadeRules,g=C.GAMES[id];document.getElementById('game-rules-content').innerHTML=`<h2 id="rules-heading">${g.name} · 방법 보기</h2><p>${rules[id]}</p><p>진행과 완료 기록은 이 브라우저에 저장됩니다. 자세한 방법은 게임 페이지에서 확인하세요.</p><a class="button primary" href="${g.route}">바로 플레이 →</a>`;document.getElementById('game-rules').showModal();});
const previous=showRecords;showRecords=function(){previous();const section=document.createElement('section');section.className='arcade-home-records';let rows=[],error='';try{const read=ArcadeStore.create(localStorage).records();rows=read.rows;error=read.error;}catch{error='저장소를 사용할 수 없습니다.';}section.innerHTML='<h3>오락실 4종 기록</h3>'+Object.entries(C.GAMES).map(([id,g])=>{const list=rows.filter(r=>r.game===id);return `<div class="record-summary"><h4>${g.name}</h4><p>${list.length}회 완료 · 최고 ${list.length?Math.max(...list.map(r=>r.score))+'점':'기록 없음'}</p></div>`;}).join('')+(error?'<p class="note">일부 기록을 읽지 못했습니다. 원본은 보존됩니다.</p>':'');document.getElementById('content').appendChild(section);};badge();window.addEventListener('pageshow',badge);
})();
